  // C. Reuse of expensive, stateful helpers via init/reset (optionally per-thread)
  private static final ThreadLocal<H> @TL = ThreadLocal.withInitial(() -> null); // optional isolation
  public OUT process(Input in) throws E {
    H h = @TL.get();
