class DecoderUser {
  private static final ThreadLocal<ResolvingDecoder> TL = ThreadLocal.withInitial(() -> null);
  private final Schema writer, reader;
  public Datum read(Input in) throws IOException {
    ResolvingDecoder d = TL.get();
    if (d == null) { d = DecoderFactory.get().resolvingDecoder(writer, reader, null); TL.set(d); }
    d.init(in); // rebind per-call
    Datum out = d.read();
    d.reset();
    return out;
